    '{month} material' => '{month} පාඩම් ද්‍රව්‍ය',
    'Nothing posted for this month yet.' => 'මේ මාසයට තවම කිසිවක් එකතු කර නැත.',
    'opened' => 'විවෘත කළා',
    '{name}\'s calendar' => '{name}ගේ දින දර්ශනය',
    'Classes, quizzes and tests' => 'පන්ති, ප්‍රශ්නාවලි සහ පරීක්ෂණ',
    'Some material is locked.' => 'සමහර පාඩම් ද්‍රව්‍ය අගුළු දමා ඇත.',
    'The classes marked with a padlock are still on, and the times here are right — but this month\'s fee for them is not settled yet, so the recordings, notes and quizzes stay shut until it is.' => 'අගුළු ලකුණ ඇති පන්ති තවමත් පැවැත්වේ, මෙහි වේලාවන් නිවැරදියි — නමුත් ඒවායේ මේ මාසයේ ගාස්තුව තවම ගෙවා නැති නිසා, ගෙවන තුරු පටිගත කිරීම්, සටහන් සහ ප්‍රශ්නාවලි වසා ඇත.',
    'Next up' => 'ඊළඟට',
    'The next 30 days.' => 'ඉදිරි දින 30.',
    'Nothing scheduled.' => 'කිසිවක් සැලසුම් කර නැත.',
    'Material locked until the fee is settled' => 'ගාස්තුව ගෙවන තුරු පාඩම් ද්‍රව්‍ය අගුළු දමා ඇත',
    'at {time}' => '{time}ට',
    'This month\'s fee is not settled, so the material stays locked. The class still runs.' => 'මේ මාසයේ ගාස්තුව ගෙවා නැති නිසා පාඩම් ද්‍රව්‍ය අගුළු දමා ඇත. පන්තිය නම් පැවැත්වේ.',
    '+{n} more' => '+තවත් {n}',
    'Quiz due' => 'ප්‍රශ්නාවලිය අවසන් දිනය',
    'Quiz opens' => 'ප්‍රශ්නාවලිය විවෘත වේ',
    'Exam' => 'විභාගය',
    'Test' => 'පරීක්ෂණය',
    'Extra class' => 'අමතර පන්තිය',
    'Holiday' => 'නිවාඩු දිනය',
    'Notice' => 'දැන්වීම',
    'Zoom recording' => 'Zoom පටිගත කිරීම්',
    'Reading material' => 'කියවීම් ද්‍රව්‍ය',
    'Video' => 'වීඩියෝ',
    'Link' => 'සබැඳිය',
    'Recording' => 'පටිගත කිරීම්',
    'Material' => 'පාඩම් ද්‍රව්‍ය',

    // Quiz pages, parent pages, study assistant
    'You\'re welcome! Ask me anything else about your classes.' => 'සතුටුයි! ඔබේ පන්ති ගැන වෙනත් ඕනෑම දෙයක් අහන්න.',
    'Hi! I can answer questions about your classes -- the next class, quizzes, marks, fees and new notes. Try one of these:' => 'ආයුබෝවන්! ඔබේ පන්ති ගැන ප්‍රශ්නවලට මට උත්තර දෙන්න පුළුවන් -- ඊළඟ පන්තිය, ප්‍රශ්නාවලි, ලකුණු, ගාස්තු සහ අලුත් සටහන්. මේවායින් එකක් අහලා බලන්න:',
    'Hi! I can answer questions about {name}\'s classes -- the next class, quizzes, marks, fees and new notes. Try one of these:' => 'ආයුබෝවන්! {name}ගේ පන්ති ගැන ප්‍රශ්නවලට මට උත්තර දෙන්න පුළුවන් -- ඊළඟ පන්තිය, ප්‍රශ්නාවලි, ලකුණු, ගාස්තු සහ අලුත් සටහන්. මේවායින් එකක් අහලා බලන්න:',
    'I know about:' => 'මම දන්නා දේ:',
    'when classes, quizzes and exams are' => 'පන්ති, ප්‍රශ්නාවලි සහ විභාග තියෙන්නේ කවදාද',
    'marks and progress' => 'ලකුණු සහ ප්‍රගතිය',
    'this month\'s fees' => 'මේ මාසයේ ගාස්තු',
    'new notes, recordings and videos' => 'අලුත් සටහන්, පටිගත කිරීම් සහ වීඩියෝ',
    'I can\'t explain science topics -- for that, use the class notes or ask the teacher.' => 'විද්‍යා පාඩම් පැහැදිලි කරන්න මට බැහැ -- ඒ සඳහා පන්ති සටහන් බලන්න, නැත්නම් ගුරුතුමියගෙන් අහන්න.',
    'You have no classes on the calendar for the next three weeks.' => 'ඉදිරි සති තුන තුළ ඔබේ දින දර්ශනයේ පන්ති නැහැ.',
    '{name} has no classes on the calendar for the next three weeks.' => 'ඉදිරි සති තුන තුළ {name}ගේ දින දර්ශනයේ පන්ති නැහැ.',
    'The next class is {title} {when}, room {room} -- {countdown}.' => 'ඊළඟ පන්තිය {title}, {when}, කාමරය {room} -- {countdown}.',
    'The next class is {title} {when} -- {countdown}.' => 'ඊළඟ පන්තිය {title}, {when} -- {countdown}.',
    'This month\'s fee for that class isn\'t settled yet, so the notes and recordings are locked. The class itself still runs.' => 'ඒ පන්තියේ මේ මාසයේ ගාස්තුව තවම ගෙවා නැති නිසා සටහන් සහ පටිගත කිරීම් අගුළු දමා ඇත. පන්තිය නම් සුපුරුදු පරිදි පැවැත්වේ.',
    'Tomorrow ({date})' => 'හෙට ({date})',
    'The next 7 days' => 'ඉදිරි දින 7',
    '{label}: nothing on the calendar.' => '{label}: දින දර්ශනයේ කිසිවක් නැත.',
    '...and {n} more on the calendar.' => '...සහ දින දර්ශනයේ තවත් {n}ක්.',
    'No exams or tests are scheduled for the next two months.' => 'ඉදිරි මාස දෙක තුළ විභාග හෝ පරීක්ෂණ සැලසුම් කර නැත.',
    'You\'re all caught up -- no quizzes waiting.' => 'ඔබ සියල්ල අවසන් කර ඇත -- බලා සිටින ප්‍රශ්නාවලි නැත.',
    'No quizzes are waiting for {name} right now.' => 'දැනට {name} වෙනුවෙන් බලා සිටින ප්‍රශ්නාවලි නැත.',
    '{n} more is in a class whose fee isn\'t settled this month.' => 'මේ මාසයේ ගාස්තුව නොගෙවූ පන්තියක තවත් {n}ක් ඇත.',
    '{n} more are in a class whose fee isn\'t settled this month.' => 'මේ මාසයේ ගාස්තුව නොගෙවූ පන්තිවල තවත් {n}ක් ඇත.',
    'My classes' => 'මගේ පන්ති',
    'open now, closes {when}' => 'දැන් විවෘතයි, {when} වසා දමයි',
    'opens {when}' => '{when} විවෘත වේ',
    '1 quiz is open now:' => 'දැන් ප්‍රශ්නාවලි 1ක් විවෘතයි:',
    '{n} quizzes are open now:' => 'දැන් ප්‍රශ්නාවලි {n}ක් විවෘතයි:',
    'Nothing open right now, but coming up:' => 'දැනට කිසිවක් විවෘත නැත, නමුත් ඉදිරියට:',
    '{n} more is locked until this month\'s fee is settled.' => 'මේ මාසයේ ගාස්තුව ගෙවන තුරු තවත් {n}ක් අගුළු දමා ඇත.',
    '{n} more are locked until this month\'s fee is settled.' => 'මේ මාසයේ ගාස්තුව ගෙවන තුරු තවත් {n}ක් අගුළු දමා ඇත.',
    'Go to my classes' => 'මගේ පන්තිවලට යන්න',
    'You haven\'t had a quiz marked yet. Marks show up here as soon as one is.' => 'ඔබේ කිසිදු ප්‍රශ්නාවලියකට තවම ලකුණු දමා නැත. ලකුණු දැමූ විගස මෙහි පෙන්වයි.',
    '{name} hasn\'t had a quiz marked yet. Marks show up here as soon as one is.' => '{name}ගේ කිසිදු ප්‍රශ්නාවලියකට තවම ලකුණු දමා නැත. ලකුණු දැමූ විගස මෙහි පෙන්වයි.',
    'below the pass mark' => 'සමත් ලකුණට අඩුයි',
    'Latest marks:' => 'නවතම ලකුණු:',
    'Average over these: {n}%.' => 'මේවායේ සාමාන්‍යය: {n}%.',
    'There isn\'t enough yet to measure progress -- it starts once there are quiz marks, attendance or material opened.' => 'ප්‍රගතිය මැනීමට තවම ප්‍රමාණවත් දත්ත නැත -- ප්‍රශ්නාවලි ලකුණු, පැමිණීම හෝ විවෘත කළ ද්‍රව්‍ය ඇති වූ පසු එය ආරම්භ වේ.',
    'You\'re at {level} -- an overall score of {score} out of 100.' => 'ඔබ සිටින්නේ {level} මට්ටමේ -- සමස්ත ලකුණ 100න් {score}.',
    '{name} is at {level} -- an overall score of {score} out of 100.' => '{name} සිටින්නේ {level} මට්ටමේ -- සමස්ත ලකුණ 100න් {score}.',
    'It combines quiz marks (60%), attendance (25%) and material opened (15%).' => 'එය ප්‍රශ්නාවලි ලකුණු (60%), පැමිණීම (25%) සහ විවෘත කළ ද්‍රව්‍ය (15%) එකතු කර ගණනය කරයි.',
    'See the full progress page' => 'සම්පූර්ණ ප්‍රගති පිටුව බලන්න',
    'You are not enrolled in any classes right now.' => 'ඔබ දැනට කිසිදු පන්තියකට ලියාපදිංචි වී නැත.',
    '{name} is not enrolled in any classes right now.' => '{name} දැනට කිසිදු පන්තියකට ලියාපදිංචි වී නැත.',
    'free card, nothing to pay' => 'නොමිලේ කාඩ්පත, ගෙවීමට කිසිවක් නැත',
    'the {month} fee hasn\'t been issued yet' => '{month} ගාස්තුව තවම නිකුත් කර නැත',
    'paid' => 'ගෙවා ඇත',
    'waived' => 'නිදහස් කර ඇත',
    'Rs. {n} overdue' => 'රු. {n} කල් ඉකුත්',
    'Rs. {n} to pay' => 'රු. {n} ගෙවිය යුතුයි',
    '{month} fees:' => '{month} ගාස්තු:',
    'Outstanding: Rs. {n}. The notes, recordings and quizzes for those classes open again once it\'s paid.' => 'ගෙවිය යුතු: රු. {n}. එය ගෙවූ පසු එම පන්තිවල සටහන්, පටිගත කිරීම් සහ ප්‍රශ්නාවලි නැවත විවෘත වේ.',
    'Everything for {month} is settled.' => '{month} සඳහා සියල්ල ගෙවා ඇත.',
    'Fee history' => 'ගාස්තු ඉතිහාසය',
    'Nothing new to open right now.' => 'දැනට විවෘත කිරීමට අලුත් දෙයක් නැත.',
    'There is material in classes whose fee isn\'t settled this month -- it opens once it is.' => 'මේ මාසයේ ගාස්තුව නොගෙවූ පන්තිවල පාඩම් ද්‍රව්‍ය ඇත -- ගෙවූ පසු ඒවා විවෘත වේ.',
    'Latest:' => 'නවතම:',
    'Open my classes' => 'මගේ පන්ති විවෘත කරන්න',
    'the teacher' => 'ගුරුතුමිය',
    'Your science teacher is {who}.' => 'ඔබේ විද්‍යා ගුරුතුමිය {who}.',
    'For a question about the lesson, ask at the next class, or contact the office at your branch.' => 'පාඩම ගැන ප්‍රශ්නයක් නම් ඊළඟ පන්තියේදී අහන්න, නැත්නම් ඔබේ ශාඛාවේ කාර්යාලය අමතන්න.',
    'That\'s a science question, and I\'m only here for things like classes, marks and fees -- I don\'t explain lessons, because a wrong answer could cost you marks.' => 'ඒක විද්‍යා ප්‍රශ්නයක්. මම ඉන්නේ පන්ති, ලකුණු, ගාස්තු වගේ දේවල් වලට විතරයි -- වැරදි උත්තරයක් නිසා ඔබට ලකුණු අඩු විය හැකි නිසා මම පාඩම් පැහැදිලි කරන්නේ නැහැ.',
    'Check the notes and recordings for that lesson, or ask the teacher at the next class.' => 'ඒ පාඩමේ සටහන් සහ පටිගත කිරීම් බලන්න, නැත්නම් ඊළඟ පන්තියේදී ගුරුතුමියගෙන් අහන්න.',
    'Sorry, I didn\'t understand that one. I can tell you about classes, quizzes, exams, marks, progress, fees and new notes. Try one of these:' => 'සමාවෙන්න, ඒක මට තේරුණේ නැහැ. පන්ති, ප්‍රශ්නාවලි, විභාග, ලකුණු, ප්‍රගතිය, ගාස්තු සහ අලුත් සටහන් ගැන මට කියන්න පුළුවන්. මේවායින් එකක් අහලා බලන්න:',
