    'Any quizzes due?' => 'කරන්න තියෙන ප්‍රශ්නාවලි තියෙනවද?',
    'My latest marks' => 'මගේ නවතම ලකුණු',
    'Have I paid this month?' => 'මම මේ මාසයට ගෙවලද?',
    'New notes or recordings?' => 'අලුත් සටහන් හෝ පටිගත කිරීම් තියෙනවද?',
    'Any exams coming up?' => 'ඉදිරියට විභාග තියෙනවද?',
    'Open the study assistant' => 'අධ්‍යයන සහායකයා විවෘත කරන්න',
    'Study assistant' => 'අධ්‍යයන සහායකයා',
    'About your child\'s classes' => 'ඔබේ දරුවාගේ පන්ති ගැන',
    'About your classes, marks and fees' => 'ඔබේ පන්ති, ලකුණු සහ ගාස්තු ගැන',
    'Close' => 'වසන්න',
    'Ask about classes, quizzes, marks, fees...' => 'පන්ති, ප්‍රශ්නාවලි, ලකුණු, ගාස්තු ගැන අහන්න...',
    'Your question' => 'ඔබේ ප්‍රශ්නය',
    'Ask' => 'අහන්න',
    'Checking…' => 'පරීක්ෂා කරමින්…',
    'Sorry, something went wrong.' => 'සමාවෙන්න, යමක් වැරදුණා.',
    'This page has been open a while. Refresh it and ask again.' => 'මෙම පිටුව බොහෝ වේලාවක් විවෘතව තිබුණා. එය අලුත් කර නැවත අහන්න.',
    'I couldn\'t reach the server just now. Try again in a moment.' => 'මේ මොහොතේ සර්වරයට සම්බන්ධ වීමට නොහැකි විය. මදකින් නැවත උත්සාහ කරන්න.',
    'Your answer' => 'ඔබේ උත්තරය',
    '{n} of {t} answered.' => '{t}න් {n}කට උත්තර දී ඇත.',
    'Unanswered questions score zero.' => 'උත්තර නොදුන් ප්‍රශ්නවලට ලකුණු ශුන්‍යයි.',
    'Saving...' => 'සුරකිමින්...',
    'Saved' => 'සුරැකුණා',
    'Could not save.' => 'සුරැකීමට නොහැකි විය.',
    'Offline - your answer is not saved yet.' => 'අන්තර්ජාලය නැත - ඔබේ උත්තරය තවම සුරැකී නැත.',
    'Time is up. Handing your paper in.' => 'කාලය අවසන්. ඔබේ පත්‍රය භාර දෙමින්.',
    'Handed in {when}' => '{when} භාර දුන්නා',
    '{a} out of {b} marks' => 'ලකුණු {b}න් {a}',
    'Not marked yet' => 'තවම ලකුණු දමා නැත',
    'The time ran out and this was handed in automatically.' => 'කාලය අවසන් වූ නිසා මෙය ස්වයංක්‍රීයව භාර දෙන ලදී.',
    'Some answers are still being marked. This score may go up.' => 'සමහර උත්තරවලට තවම ලකුණු දමමින් පවතී. මෙම ලකුණ වැඩි විය හැක.',
    'The answers appear here once the quiz closes on {when}.' => '{when} ප්‍රශ්නාවලිය වසා දැමූ පසු නිවැරදි උත්තර මෙහි පෙන්වයි.',
    'Your answers' => 'ඔබේ උත්තර',
    'You wrote:' => 'ඔබ ලිව්වේ:',
    'Expected:' => 'අපේක්ෂිත උත්තරය:',
    'your answer' => 'ඔබේ උත්තරය',
    'You left this blank.' => 'ඔබ මෙය හිස්ව තැබුවා.',
    'The {month} fee is settled.' => '{month} ගාස්තුව ගෙවා ඇත.',
    'The {month} fee was waived.' => '{month} ගාස්තුව නිදහස් කර ඇත.',
    'The {month} fee is overdue. Class material stays locked until it is settled.' => '{month} ගාස්තුව කල් ඉකුත් වී ඇත. ගෙවන තුරු පාඩම් ද්‍රව්‍ය අගුළු දමා ඇත.',
    'The {month} fee is not settled yet.' => '{month} ගාස්තුව තවම ගෙවා නැත.',
    'The {month} fee has not been issued yet.' => '{month} ගාස්තුව තවම නිකුත් කර නැත.',
    'Progress report' => 'ප්‍රගති වාර්තාව',
    'Overall' => 'සමස්ත',
    'Outstanding this month' => 'මේ මාසයේ ගෙවිය යුතු',
    'Rs. {n}' => 'රු. {n}',
