    'Confirm new password' => 'අලුත් මුරපදය තහවුරු කරන්න',
    'Set new password' => 'අලුත් මුරපදය සකසන්න',
    'Back to login' => 'පිවිසුමට ආපසු',
    'Have you confirmed who is asking? A new code replaces any earlier one.' => 'ඉල්ලන්නේ කවුදැයි ඔබ තහවුරු කළාද? අලුත් කේතයක් පෙර කේතය අවලංගු කරයි.',
    'Password reset code' => 'මුරපද යළි සැකසීමේ කේතය',
    'Parent reset code' => 'දෙමාපිය යළි සැකසීමේ කේතය',
    'Forgotten password' => 'අමතක වූ මුරපදය',
    'Confirm who is asking first (in person, or by calling the phone number on file). The code is shown once and works for 30 minutes.' => 'මුලින්ම ඉල්ලන්නේ කවුදැයි තහවුරු කරන්න (පෞද්ගලිකව, නැතහොත් වාර්තාවල ඇති දුරකථන අංකයට ඇමතීමෙන්). කේතය එක් වරක් පෙන්වන අතර මිනිත්තු 30ක් වැඩ කරයි.',
    'Issue a password reset code' => 'මුරපද යළි සැකසීමේ කේතයක් නිකුත් කරන්න',
    'Settings' => 'සැකසුම්',
    'Payment slips to check' => 'පරීක්ෂා කළ යුතු ගෙවීම් ස්ලිප් පත්',
    'New enrolment inquiries' => 'අලුත් ලියාපදිංචි විමසීම්',
    'Open help requests' => 'විවෘත උදව් ඉල්ලීම්',
    'Approvals waiting for you' => 'ඔබේ අනුමැතිය බලාපොරොත්තු වන දේ',
    'Unpaid fees this month' => 'මේ මාසයේ නොගෙවූ ගාස්තු',
    'Marked absent today' => 'අද නොපැමිණි ලෙස සටහන් වූ',
    'Today\'s work' => 'අද කළ යුතු වැඩ',
    'Nothing waiting' => 'කිසිවක් බලාපොරොත්තුවෙන් නැත',
    'Across all branches' => 'සියලු ශාඛා',
    'In your branch' => 'ඔබේ ශාඛාවේ',
    'Please log in again.' => 'කරුණාකර නැවත පිවිසෙන්න.',
    'Your password was changed. Please log in again.' => 'ඔබේ මුරපදය වෙනස් කර ඇත. කරුණාකර නැවත පිවිසෙන්න.',
    'Your access was changed. Please log in again.' => 'ඔබේ ප්‍රවේශය වෙනස් කර ඇත. කරුණාකර නැවත පිවිසෙන්න.',
    // Topics, past papers, register, learning gaps
    'Choose present, late or absent.' => 'පැමිණි, ප්‍රමාද හෝ නොපැමිණි තෝරන්න.',
    'That class is not in your branch.' => 'එම පන්තිය ඔබේ ශාඛාවේ නොවේ.',
    'Class register' => 'පන්ති ලේඛනය',
    'Choose a class and a date that is not in the future.' => 'පන්තියක් සහ අනාගත නොවන දිනයක් තෝරන්න.',
    'Register saved: {n} students, {a} absent, {f} families alerted.' => 'ලේඛනය සුරැකුවා: සිසුන් {n}, නොපැමිණි {a}, පවුල් {f}කට දැනුම් දුන්නා.',
    'Not tagged with a topic' => 'ඒකකයක් සලකුණු කර නැත',
    'Learning gaps' => 'ඉගෙනීමේ හිඩැස්',
    'Past papers' => 'පසුගිය ප්‍රශ්න පත්‍ර',
    'Add a past paper' => 'ප්‍රශ්න පත්‍රයක් එක් කරන්න',
    'Choose the grade, year, paper type and medium.' => 'ශ්‍රේණිය, වර්ෂය, පත්‍ර වර්ගය සහ මාධ්‍යය තෝරන්න.',
    'Attach the paper (PDF, PNG or JPG).' => 'ප්‍රශ්න පත්‍රය අමුණන්න (PDF, PNG හෝ JPG).',
    'Paper published for Grade {n} students.' => '{n} ශ්‍රේණියේ සිසුන් සඳහා ප්‍රශ්න පත්‍රය පළ කළා.',
    'Updated.' => 'යාවත්කාලීන කළා.',
    'That area is for students.' => 'එම කොටස සිසුන් සඳහාය.',
    'That paper does not exist.' => 'එම ප්‍රශ්න පත්‍රය නොමැත.',
    'Topics' => 'ඒකක',
    'Topic added.' => 'ඒකකය එක් කළා.',
    'That topic already exists for this grade.' => 'එම ඒකකය මෙම ශ්‍රේණියට දැනටමත් ඇත.',
    'The topic could not be saved.' => 'ඒකකය සුරැකිය නොහැකි විය.',
    'Topic updated.' => 'ඒකකය යාවත්කාලීන කළා.',
    'Topic hidden from the pickers. Work already tagged keeps it.' => 'ඒකකය තේරීම් ලැයිස්තුවලින් සැඟවුවා. දැනටමත් සලකුණු කළ වැඩවල එය රැඳේ.',
    'Topic restored.' => 'ඒකකය නැවත ලබා දුන්නා.',
    'That topic does not exist.' => 'එම ඒකකය නොමැත.',
    'Choose a grade and subject.' => 'ශ්‍රේණියක් සහ විෂයයක් තෝරන්න.',
    'Give the topic a name (up to 255 characters).' => 'ඒකකයට නමක් දෙන්න (අකුරු 255 දක්වා).',
    'The unit number must be between 1 and 99.' => 'ඒකක අංකය 1ත් 99ත් අතර විය යුතුය.',
    'Students who scanned in are already marked present. Mark the rest, then save.' => 'ස්කෑන් කර පැමිණි සිසුන් දැනටමත් පැමිණි ලෙස සලකුණු වී ඇත. ඉතිරි අය සලකුණු කර සුරකින්න.',
    'Open register' => 'ලේඛනය විවෘත කරන්න',
    'This is an older date: saving updates the record but does not alert families.' => 'මෙය පැරණි දිනයකි: සුරැකීමෙන් වාර්තාව යාවත්කාලීන වන නමුත් පවුල්වලට දැනුම් නොදේ.',
    'Each student marked absent sends one alert to their family (portal notice, and a WhatsApp message prepared for the office to send).' => 'නොපැමිණි ලෙස සලකුණු කරන සෑම සිසුවෙකු ගැනම ඔවුන්ගේ පවුලට එක් දැනුම්දීමක් යයි (ද්වාරයේ දැනුම්දීමක්, සහ කාර්යාලයට යැවීමට සූදානම් කළ WhatsApp පණිවිඩයක්).',
    'Not marked' => 'සලකුණු කර නැත',
    'Mark everyone not marked as absent' => 'සලකුණු නොකළ සියල්ලන් නොපැමිණි ලෙස සලකුණු කරන්න',
    'Family alerted' => 'පවුලට දැනුම් දුන්නා',
    'Save register' => 'ලේඛනය සුරකින්න',
    'Topic (unit)' => 'ඒකකය',
    'No topics for this grade yet.' => 'මෙම ශ්‍රේණියට තවම ඒකක නැත.',
    'Add the units' => 'ඒකක එක් කරන්න',
    'No topic' => 'ඒකකයක් නැත',
    'Tagging work by unit lets the learning-gaps page show which units the class finds hard.' => 'වැඩ ඒකක අනුව සලකුණු කිරීමෙන්, පන්තියට අපහසු ඒකක මොනවාදැයි ඉගෙනීමේ හිඩැස් පිටුවේ පෙන්වයි.',
    'From marked quizzes (latest attempt) and marked homework. Unanswered questions count as zero; answers waiting to be marked are left out.' => 'ලකුණු දැමූ ප්‍රශ්නාවලි (අවසන් උත්සාහය) සහ ලකුණු දැමූ ගෙදර වැඩ මත පදනම්ව. පිළිතුරු නොදුන් ප්‍රශ්නවලට බිංදුව ගැනේ; ලකුණු දැමීමට බලා සිටින පිළිතුරු ඇතුළත් නොවේ.',
    'Homework' => 'ගෙදර වැඩ',
    'No topics for this grade yet, so everything shows as "not tagged".' => 'මෙම ශ්‍රේණියට තවම ඒකක නැති නිසා, සියල්ල "සලකුණු කර නැත" ලෙස පෙන්වයි.',
    'By topic (hardest first)' => 'ඒකක අනුව (අපහසුම පළමුව)',
    'No marked work yet for this class.' => 'මෙම පන්තියට තවම ලකුණු දැමූ වැඩ නැත.',
    'Class average' => 'පන්ති සාමාන්‍යය',
    'Students assessed' => 'ඇගයූ සිසුන්',
    'Below {n}%' => '{n}%ට අඩු',
    'and {n} more' => 'සහ තවත් {n}ක්',
    'By student (lowest first)' => 'සිසුන් අනුව (අඩුම පළමුව)',
    'Weakest topic' => 'දුර්වලම ඒකකය',
    'Questions most often wrong' => 'බොහෝ විට වැරදුණු ප්‍රශ්න',
    'Needs at least three marked answers per question.' => 'එක් ප්‍රශ්නයකට අවම වශයෙන් ලකුණු දැමූ පිළිතුරු තුනක් අවශ්‍යයි.',
    '{a} of {b} got full marks' => '{b} දෙනාගෙන් {a} දෙනෙක් සම්පූර්ණ ලකුණු ගත්තා',
    'Work not done' => 'නොකළ වැඩ',
    'Nothing past its deadline yet.' => 'තවම අවසන් දිනය පසු වූ කිසිවක් නැත.',
    '{n} did not sit it' => '{n} දෙනෙක් එය කළේ නැත',
    '{n} did not hand it in' => '{n} දෙනෙක් එය භාර දුන්නේ නැත',
    'PDF, PNG or JPG, up to 15 MB each. Upload only papers you are allowed to share with your students.' => 'PDF, PNG හෝ JPG, එකක් 15 MB දක්වා. ඔබේ සිසුන් සමඟ බෙදා ගැනීමට අවසර ඇති ප්‍රශ්න පත්‍ර පමණක් උඩුගත කරන්න.',
    'Year' => 'වර්ෂය',
    'Paper type' => 'පත්‍ර වර්ගය',
    'Medium' => 'මාධ්‍යය',
    'Leave empty to name it from the grade, type and year' => 'ශ්‍රේණිය, වර්ගය සහ වර්ෂය අනුව නම් කිරීමට හිස්ව තබන්න',
    'Whole paper (no single topic)' => 'සම්පූර්ණ පත්‍රය (එක් ඒකකයක් නොවේ)',
    'Paper' => 'ප්‍රශ්න පත්‍රය',
    'Marking scheme (optional)' => 'ලකුණු දීමේ පටිපාටිය (අත්‍යවශ්‍ය නොවේ)',
    'Students may see the marking scheme now' => 'සිසුන්ට දැන් ලකුණු දීමේ පටිපාටිය බැලිය හැක',
    'Cancel' => 'අවලංගු කරන්න',
    'Term tests, model papers and marking schemes by grade. Students see published papers of their own grade once the month is paid.' => 'ශ්‍රේණිය අනුව වාර විභාග, ආදර්ශ ප්‍රශ්න පත්‍ර සහ ලකුණු දීමේ පටිපාටි. මාසයේ ගාස්තුව ගෙවූ පසු සිසුන්ට තම ශ්‍රේණියේ පළ කළ පත්‍ර පෙනේ.',
    'No papers yet.' => 'තවම ප්‍රශ්න පත්‍ර නැත.',
    'Marking scheme released' => 'ලකුණු දීමේ පටිපාටිය නිකුත් කර ඇත',
    'Marking scheme hidden' => 'ලකුණු දීමේ පටිපාටිය සඟවා ඇත',
    'Marking scheme' => 'ලකුණු දීමේ පටිපාටිය',
    'Unpublish' => 'පළ කිරීම ඉවත් කරන්න',
    'Hide marking scheme' => 'ලකුණු දීමේ පටිපාටිය සඟවන්න',
    'Release marking scheme' => 'ලකුණු දීමේ පටිපාටිය නිකුත් කරන්න',
    'Remove' => 'ඉවත් කරන්න',
    'Papers your teacher has shared for your grade. Try them under exam time, then check the marking scheme when it is released.' => 'ඔබේ ගුරුවරිය ඔබේ ශ්‍රේණියට බෙදාගත් ප්‍රශ්න පත්‍ර. විභාග කාලය තුළ ඒවා කර බලන්න, ලකුණු දීමේ පටිපාටිය නිකුත් කළ පසු පරීක්ෂා කරන්න.',
    'No papers for your grade yet.' => 'ඔබේ ශ්‍රේණියට තවම ප්‍රශ්න පත්‍ර නැත.',
    'Some papers are locked until this month\'s fee is settled.' => 'මේ මාසයේ ගාස්තුව ගෙවන තුරු සමහර ප්‍රශ්න පත්‍ර අගුළු දමා ඇත.',
    'Download paper' => 'ප්‍රශ්න පත්‍රය බාගන්න',
    'Locked' => 'අගුළු දමා ඇත',
    'Register' => 'ලේඛනය',
    'Your units for each grade. Tag notes, quizzes, questions and homework with them to see which units the class finds hard.' => 'සෑම ශ්‍රේණියකටම ඔබේ ඒකක. පන්තියට අපහසු ඒකක දැකීමට සටහන්, ප්‍රශ්නාවලි, ප්‍රශ්න සහ ගෙදර වැඩ ඒවායින් සලකුණු කරන්න.',
    'Add a unit' => 'ඒකකයක් එක් කරන්න',
    'Unit no.' => 'ඒකක අංකය',
    'Unit name (English)' => 'ඒකකයේ නම (ඉංග්‍රීසි)',
    'Unit name (Sinhala)' => 'ඒකකයේ නම (සිංහල)',
    'Add' => 'එක් කරන්න',
    'No units for this grade yet. Add them above, in the order you teach them.' => 'මෙම ශ්‍රේණියට තවම ඒකක නැත. ඔබ උගන්වන පිළිවෙළට ඉහතින් ඒවා එක් කරන්න.',
    'Tagged items' => 'සලකුණු කළ අයිතම',
    'Save' => 'සුරකින්න',
    'Hide' => 'සඟවන්න',
    'Restore' => 'නැවත ලබා දෙන්න',
    'First term test' => 'පළමු වාර විභාගය',
    'Second term test' => 'දෙවන වාර විභාගය',
    'Third term test' => 'තෙවන වාර විභාගය',
    'Model paper' => 'ආදර්ශ ප්‍රශ්න පත්‍රය',
    'Provincial paper' => 'පළාත් ප්‍රශ්න පත්‍රය',
    'School paper' => 'පාසල් ප්‍රශ්න පත්‍රය',
    'Sinhala' => 'සිංහල',
    'English' => 'ඉංග්‍රීසි',
    'Tamil' => 'දෙමළ',
    // Public site v3 (teacher-centred)
    'Harshani Madhuwanthi' => 'හර්ෂනී මධුවන්ති',
    'Harshani Madhuwanthi Wanasinghe' => 'හර්ෂනී මධුවන්ති වනසිංහ',
    'Miss' => 'ආචාර්ය',

    // Classes landing page (/our-classes)
    'Pick a branch' => 'ශාඛාවක් තෝරන්න',
    'See the classes, photos and timings for each branch, then view that branch\'s classes.' => 'සෑම ශාඛාවකම පන්ති, ඡායාරූප සහ වේලාවන් බලා, පසුව එම ශාඛාවේ පන්ති බලන්න.',
    'No branch is published on the website yet.' => 'තවම වෙබ් අඩවියේ ශාඛාවක් පළ කර නැත.',
    '{n} classes at this branch, physical and online.' => 'මෙම ශාඛාවේ පන්ති {n}ක්, සෘජුව සහ මාර්ගගතව.',
    'Watch video' => 'වීඩියෝව බලන්න',
    'Branch video link' => 'ශාඛා වීඩියෝ සබැඳිය',
    'Optional. Paste a YouTube, Facebook or other video link. Shown as a "Watch video" button on the public branches/classes pages.' => 'අත්‍යවශ්‍ය නැත. YouTube, Facebook හෝ වෙනත් වීඩියෝ සබැඳියක් ඇලවන්න. ප්‍රසිද්ධ ශාඛා/පන්ති පිටුවල "වීඩියෝව බලන්න" බොත්තමක් ලෙස පෙන්වයි.',
    'Paste a YouTube, Facebook or other video link -- OR upload a video file below. Shown as a "Watch video" button on the public branches/classes pages.' => 'YouTube, Facebook හෝ වෙනත් වීඩියෝ සබැඳියක් ඇලවන්න -- නැතහොත් පහත වීඩියෝ ගොනුවක් උඩුගත කරන්න. ප්‍රසිද්ධ ශාඛා/පන්ති පිටුවල "වීඩියෝව බලන්න" බොත්තමක් ලෙස පෙන්වයි.',
    '...or upload a video file' => '...නැතහොත් වීඩියෝ ගොනුවක් උඩුගත කරන්න',
    'MP4, WEBM, MOV or OGG, up to 35MB. If both a link and a file are given, the link is used.' => 'MP4, WEBM, MOV හෝ OGG, උපරිම 35MB. සබැඳියක් සහ ගොනුවක් දෙකම දුන්නොත්, සබැඳිය පාවිච්චි වේ.',
    'MP4, WEBM, MOV or OGG, up to 35MB. If both a link and a file are given, the link is used. Leave both blank to keep the current video.' => 'MP4, WEBM, MOV හෝ OGG, උපරිම 35MB. සබැඳියක් සහ ගොනුවක් දෙකම දුන්නොත්, සබැඳිය පාවිච්චි වේ. දැනට ඇති වීඩියෝව තියා ගැනීමට දෙකම හිස්ව තබන්න.',

    // Public self-service enrolment (/enroll) + admin Enrolment Requests queue
    'Enrol now' => 'දැන් ලියාපදිංචි වන්න',
    'Enrol in a class' => 'පන්තියකට ලියාපදිංචි වන්න',
    'Pick a branch and class, fill in the details, and upload your bank deposit slip. The branch office reviews it and sets up the login.' => 'ශාඛාවක් සහ පන්තියක් තෝරන්න, විස්තර පුරවන්න, බැංකු තැන්පතු පත්‍රිකාව උඩුගත කරන්න. ශාඛා කාර්යාලය එය පරීක්ෂා කර පිවිසුම සකසනු ඇත.',
    'Online enrolment opens soon. Please contact us through the Contact page.' => 'මාර්ගගත ලියාපදිංචිය ඉක්මනින් විවෘත වේ. කරුණාකර අප අමතන්න පිටුව හරහා අප හා සම්බන්ධ වන්න.',
    'Branch and class' => 'ශාඛාව සහ පන්තිය',
    'Choose a branch first' => 'මුලින්ම ශාඛාවක් තෝරන්න',
    'Student' => 'සිසුවා',
    'Date of birth (optional)' => 'උපන් දිනය (විකල්ප)',
    'Guardian' => 'භාරකරු',
    'Guardian name' => 'භාරකරුගේ නම',
    'Guardian phone' => 'භාරකරුගේ දුරකථනය',
    'Guardian email (optional)' => 'භාරකරුගේ විද්‍යුත් තැපෑල (විකල්ප)',
    'Address (optional)' => 'ලිපිනය (විකල්ප)',
    'Payment' => 'ගෙවීම',
    'Pay the class fee by bank deposit/transfer, then upload a photo or PDF of the slip. The branch office checks it before the login is created.' => 'බැංකු තැන්පතුව/මාරුව මගින් පන්ති ගාස්තුව ගෙවා, පත්‍රිකාවේ ඡායාරූපයක් හෝ PDF එකක් උඩුගත කරන්න. පිවිසුම සෑදීමට පෙර ශාඛා කාර්යාලය එය පරීක්ෂා කරයි.',
    'Payment type' => 'ගෙවීම් වර්ගය',
    'Amount paid (optional)' => 'ගෙවූ මුදල (විකල්ප)',
    'Date paid (optional)' => 'ගෙවූ දිනය (විකල්ප)',
    'Bank (optional)' => 'බැංකුව (විකල්ප)',
    'Reference number (optional)' => 'යොමු අංකය (විකල්ප)',
    'Bank deposit slip' => 'බැංකු තැන්පතු පත්‍රිකාව',
    'JPG, PNG or PDF, up to 5MB.' => 'JPG, PNG හෝ PDF, උපරිම 5MB.',
    'These details are only used to review your enrolment and set up the student/parent logins.' => 'මෙම විස්තර ඔබේ ලියාපදිංචිය සමාලෝචනය කර සිසු/දෙමාපිය පිවිසුම් සැකසීමට පමණක් භාවිතා වේ.',
    'Send enrolment request' => 'ලියාපදිංචි ඉල්ලීම යවන්න',
    'No classes at this branch yet.' => 'මෙම ශාඛාවේ තවම පන්ති නැත.',
    'Thank you! Your enrolment request has been sent for review.' => 'ස්තූතියි! ඔබේ ලියාපදිංචි ඉල්ලීම සමාලෝචනය සඳහා යවා ඇත.',
    'Thank you! Your enrolment request and slip have been sent to the branch office for review.' => 'ස්තූතියි! ඔබේ ලියාපදිංචි ඉල්ලීම සහ පත්‍රිකාව සමාලෝචනය සඳහා ශාඛා කාර්යාලයට යවා ඇත.',
    'Attach a photo or PDF of the bank deposit slip.' => 'බැංකු තැන්පතු පත්‍රිකාවේ ඡායාරූපයක් හෝ PDF එකක් අමුණන්න.',
    'Please check the branch, class, student and guardian details, and the payment date.' => 'කරුණාකර ශාඛාව, පන්තිය, සිසුවාගේ සහ භාරකරුගේ විස්තර, සහ ගෙවීම් දිනය පරීක්ෂා කරන්න.',
    'Enrolment Requests' => 'ලියාපදිංචි ඉල්ලීම්',
    'New students who enrolled themselves on the website and uploaded a bank deposit slip.' => 'වෙබ් අඩවියේ තමන්ම ලියාපදිංචි වී බැංකු තැන්පතු පත්‍රිකාවක් උඩුගත කළ නව සිසුන්.',
    'No requests.' => 'ඉල්ලීම් නැත.',
    'Guardian:' => 'භාරකරු:',
    'Payment type:' => 'ගෙවීම් වර්ගය:',
    'View bank slip' => 'බැංකු පත්‍රිකාව බලන්න',
    'Rejected:' => 'ප්‍රතික්ෂේප කළේ:',
    'Creates the student (and parent) account and enrols them in this class.' => 'සිසු (සහ දෙමාපිය) ගිණුම සාදා, මෙම පන්තියට ඇතුළත් කරයි.',
    'Approve & Create Account' => 'අනුමත කර ගිණුම සාදන්න',
    'Reason for rejecting this request:' => 'මෙම ඉල්ලීම ප්‍රතික්ෂේප කිරීමට හේතුව:',
    'Give a reason for the rejection.' => 'ප්‍රතික්ෂේප කිරීමට හේතුවක් දෙන්න.',
    'This request has already been reviewed.' => 'මෙම ඉල්ලීම දැනටමත් සමාලෝචනය කර ඇත.',
    'The request could not be approved. Nothing was changed.' => 'ඉල්ලීම අනුමත කළ නොහැකි විය. කිසිවක් වෙනස් වූයේ නැත.',
    'That request is not in your branch.' => 'එම ඉල්ලීම ඔබේ ශාඛාවේ නැත.',
    'Approved. Student ID: {id}' => 'අනුමතයි. සිසු හැඳුනුම්පත: {id}',
    'Enrolment requests awaiting review' => 'සමාලෝචනය අපේක්ෂාවෙන් ඇති ලියාපදිංචි ඉල්ලීම්',

    // Inquiries: "Approve & Register" -- prefills the student registration form
    'Marks this inquiry responded and opens the student registration form with these details filled in.' => 'මෙම විමසීම "පිළිතුරු දුන්" ලෙස සලකුණු කර, මෙම විස්තර සමඟ සිසු ලියාපදිංචි පෝරමය විවෘත කරයි.',
    'Approve &amp; Register' => 'අනුමත කර ලියාපදිංචි කරන්න',
    'Filled in from an enrolment inquiry.' => 'ඇතුළත් කිරීමේ විමසීමකින් පුරවා ඇත.',
    'Requested grade:' => 'ඉල්ලූ ශ්‍රේණිය:',
    'check the class list matches, then set a class and save to actually create the login.' => 'පන්ති ලැයිස්තුව ගැලපෙනවාදැයි පරීක්ෂා කර, පන්තියක් තෝරා, පිවිසුම සැබවින්ම සෑදීමට සුරකින්න.',

    // Home page: "Explore our classes" teaser (full list now lives on /our-classes)
    '{classes} classes across {grades} grades, {branches} branches.' => 'ශාඛා {branches}ක, ශ්‍රේණි {grades}ක, පන්ති {classes}ක්.',
    'View all classes' => 'සියලු පන්ති බලන්න',

    // Website Content admin page: shortcut to add/manage branches shown on the Classes page
    'This section only edits the heading text above the branch list. Each box on the Classes page is one branch.' => 'මෙම කොටුව පන්ති පිටුවේ ශීර්ෂක පෙළ විතරක් වෙනස් කරයි. පන්ති පිටුවේ එක් කොටුවක් = එක් ශාඛාවක්.',
    'Add a new branch' => 'අළුත් ශාඛාවක් එකතු කරන්න',
    'Manage branches (photo, video, description)' => 'ශාඛා කළමනාකරණය (ඡායාරූපය, වීඩියෝව, විස්තරය)',

    // Public Events page (/events)
    'Events' => 'අවස්ථා',
    'Seminars & events' => 'සම්මන්ත්‍රණ සහ අවස්ථා',
    'Upcoming seminars, revision classes and events for our students.' => 'අපගේ සිසුන් සඳහා ඉදිරි සම්මන්ත්‍රණ, review පන්ති සහ අවස්ථා.',
    'No upcoming events are published yet. Check back soon.' => 'තවම ඉදිරි අවස්ථා පළ කර නැත. ඉක්මනින් නැවත බලන්න.',
    'Registration required' => 'ලියාපදිංචිය අවශ්‍යයි',

    // Text message (SMS) gateway settings
    'Text messages' => 'කෙටි පණිවිඩ',
    'Text messages (SMS)' => 'කෙටි පණිවිඩ (SMS)',
    'When a student or parent asks to reset a forgotten password, the one-time code goes to the phone number already on their account. Set up a gateway here and the code is texted automatically.' => 'සිසුවෙක් හෝ දෙමාපියෙක් අමතක වූ මුරපදයක් නැවත සැකසීමට ඉල්ලූ විට, එක් වාරයකට වලංගු කේතය ඔවුන්ගේ ගිණුමේ ඇති දුරකථන අංකයට යයි. මෙහි ගේට්වේ එකක් සකසන්න, එවිට කේතය ස්වයංක්‍රීයව කෙටි පණිවිඩයක් ලෙස යයි.',
    'Reset codes are being texted automatically.' => 'නැවත සැකසීමේ කේත ස්වයංක්‍රීයව කෙටි පණිවිඩයක් ලෙස යවනු ලැබේ.',
    'No gateway yet.' => 'තවම ගේට්වේ එකක් නැත.',
    'Reset codes are queued for the office to send by WhatsApp, which someone has to tap for each student.' => 'නැවත සැකසීමේ කේත WhatsApp මගින් යැවීමට කාර්යාලයේ පෝලිමේ තබා ඇත; සෑම සිසුවෙකුටම කෙනෙක් එය එබිය යුතුය.',
    'Send reset codes by text message' => 'නැවත සැකසීමේ කේත කෙටි පණිවිඩයෙන් යවන්න',
    'Leave this off to keep using the office WhatsApp queue.' => 'කාර්යාලයේ WhatsApp පෝලිම දිගටම භාවිත කිරීමට මෙය නිවා තබන්න.',
    'Gateway' => 'ගේට්වේ',
    'Choose a gateway' => 'ගේට්වේ එකක් තෝරන්න',
    'Choose one of the listed gateways.' => 'ලැයිස්තුගත ගේට්වේ එකක් තෝරන්න.',
    'Notify.lk and Text.lk are Sri Lankan gateways. Choose "Other" to paste the address of any gateway that accepts a web request.' => 'Notify.lk සහ Text.lk ශ්‍රී ලාංකික ගේට්වේ වේ. වෙබ් ඉල්ලීමක් පිළිගන්නා වෙනත් ගේට්වේ එකක ලිපිනය ඇලවීමට "වෙනත්" තෝරන්න.',
    'API key or token' => 'API යතුර හෝ ටෝකනය',
    'Saved. Type a new one only to replace it.' => 'සුරකින ලදි. එය වෙනස් කිරීමට පමණක් අලුත් එකක් ලියන්න.',
    'Paste the key from the gateway' => 'ගේට්වේ එකෙන් ලැබෙන යතුර අලවන්න',
    'Stored for the system and never shown again. Leaving this blank keeps the key already saved.' => 'පද්ධතිය සඳහා සුරකිනු ලැබේ, නැවත කිසිදා පෙන්වන්නේ නැත. මෙය හිස්ව තැබුවොත් දැනටමත් සුරැකි යතුර එලෙසම පවතී.',
    'User ID' => 'පරිශීලක අංකය',
    'Notify.lk only. Leave blank for the others.' => 'Notify.lk සඳහා පමණි. අනෙක් ඒවාට හිස්ව තබන්න.',
    'Sender name' => 'යවන්නාගේ නම',
    'The name the message appears to come from. It has to be one the gateway has approved for this account.' => 'පණිවිඩය එන බව පෙනෙන නම. එය මෙම ගිණුම සඳහා ගේට්වේ විසින් අනුමත කළ එකක් විය යුතුය.',
    'Gateway address' => 'ගේට්වේ ලිපිනය',
    'For "Other" only. Use {to} where the number goes and {message} where the text goes; {api_key} and {sender_id} work too. It must start with https.' => '"වෙනත්" සඳහා පමණි. අංකය යන තැන {to} සහ පෙළ යන තැන {message} භාවිත කරන්න; {api_key} සහ {sender_id} ද ක්‍රියා කරයි. එය https වලින් පටන් ගත යුතුය.',
    'Send a test message' => 'පරීක්ෂණ පණිවිඩයක් යවන්න',
    'Send one real message to your own phone to prove the gateway works, before a student has to rely on it. This uses one message from your gateway balance.' => 'සිසුවෙක් මෙය මත විශ්වාසය තබන්නට පෙර, ගේට්වේ ක්‍රියා කරන බව තහවුරු කරගැනීමට ඔබේම දුරකථනයට සැබෑ පණිවිඩයක් යවන්න. මෙය ඔබේ ගේට්වේ ශේෂයෙන් එක් පණිවිඩයක් භාවිත කරයි.',
    'Send test message' => 'පරීක්ෂණ පණිවිඩය යවන්න',
    'Save the gateway details and switch it on first.' => 'පළමුව ගේට්වේ විස්තර සුරකින්න සහ එය ක්‍රියාත්මක කරන්න.',
    'Fill in the gateway details and switch it on first.' => 'පළමුව ගේට්වේ විස්තර පුරවා එය ක්‍රියාත්මක කරන්න.',
    'Text message settings saved.' => 'කෙටි පණිවිඩ සැකසුම් සුරකින ලදි.',
    'Could not save the text message settings.' => 'කෙටි පණිවිඩ සැකසුම් සුරැකිය නොහැකි විය.',
    'Test message sent. Check the phone.' => 'පරීක්ෂණ පණිවිඩය යවන ලදි. දුරකථනය බලන්න.',
    'The gateway did not accept the message. Check the number and the details, then try again.' => 'ගේට්වේ පණිවිඩය පිළිගත්තේ නැත. අංකය සහ විස්තර පරීක්ෂා කර නැවත උත්සාහ කරන්න.',
    'This is a test message from the class portal. The gateway is working.' => 'මෙය පන්ති ද්වාරයෙන් එන පරීක්ෂණ පණිවිඩයකි. ගේට්වේ ක්‍රියා කරයි.',

    'Class timetable' => 'පන්ති කාලසටහන',

    // Seminar posters on the home page
    'Notices' => 'දැන්වීම්',
    'Home page: seminar posters and notices' => 'මුල් පිටුව: සම්මන්ත්‍රණ පෝස්ටර් සහ දැන්වීම්',
    'Heading above the posters' => 'පෝස්ටර් වලට ඉහළින් ඇති ශීර්ෂය',
    'Line under that heading (leave blank to hide)' => 'එම ශීර්ෂයට පහළින් ඇති පේළිය (සැඟවීමට හිස්ව තබන්න)',

    // Online class joining
    'Join the class now' => 'දැන් පන්තියට එක්වන්න',
    'Online class link' => 'මාර්ගගත පන්තියේ සබැඳිය',
    'Join the online class' => 'මාර්ගගත පන්තියට එක්වන්න',

    // Website content editor ('English' and 'Sinhala' are already above)
    'The wording and photos on the public home, about and contact pages. Leave a box blank to use the original wording, which is shown as faint text inside it.' => 'ප්‍රසිද්ධ මුල් පිටුව, පන්ති ගැන සහ අමතන්න පිටුවල වචන සහ ඡායාරූප. මුල් වචන භාවිත කිරීමට කොටුව හිස්ව තබන්න; ඒවා කොටුව තුළ සිහින් අකුරෙන් පෙන්වයි.',
    'JPG, PNG or WEBP, up to 3MB. The same photo is used in both languages.' => 'JPG, PNG හෝ WEBP, උපරිම 3MB. එකම ඡායාරූපය භාෂා දෙකේම භාවිත වේ.',
    'Home page: the top of the page' => 'මුල් පිටුව: පිටුවේ ඉහළ කොටස',
    'Home page: "Your teacher"' => 'මුල් පිටුව: "ඔබේ ගුරුතුමිය"',
    'Home page: how the classes work' => 'මුල් පිටුව: පන්ති ක්‍රියා කරන ආකාරය',
    'Home page: the four steps to join' => 'මුල් පිටුව: එක්වීමට පියවර හතර',
    'Home page: branches and classes' => 'මුල් පිටුව: ශාඛා සහ පන්ති',
    'Home page: questions parents ask' => 'මුල් පිටුව: දෙමාපියන් අසන ප්‍රශ්න',
    'Home page: the inquiry form' => 'මුල් පිටුව: විමසීම් පෝරමය',
    'About page' => 'පන්ති ගැන පිටුව',
    'Contact page' => 'අමතන්න පිටුව',
    'Photos' => 'ඡායාරූප',
    'Email address (leave blank to hide)' => 'විද්‍යුත් තැපැල් ලිපිනය (සැඟවීමට හිස්ව තබන්න)',
    'WhatsApp number (leave blank to hide)' => 'WhatsApp අංකය (සැඟවීමට හිස්ව තබන්න)',
    'Website address (leave blank to hide)' => 'වෙබ් අඩවි ලිපිනය (සැඟවීමට හිස්ව තබන්න)',
    'Facebook page address (leave blank to hide)' => 'ෆේස්බුක් පිටුවේ ලිපිනය (සැඟවීමට හිස්ව තබන්න)',
    'Science classes' => 'විද්‍යා පන්ති',
    'Grades {r}' => '{r} ශ්‍රේණි',
    'About the classes' => 'පන්ති ගැන',
    'Contact' => 'අමතන්න',
    'That email address is not valid.' => 'එම විද්‍යුත් තැපැල් ලිපිනය වලංගු නැත.',
    'Give a phone number or an email so the office can reply.' => 'කාර්යාලයට පිළිතුරු දීමට දුරකථන අංකයක් හෝ විද්‍යුත් තැපෑලක් දෙන්න.',
    'Home' => 'මුල් පිටුව',
    'About' => 'අප ගැන',
    'Login' => 'පිවිසෙන්න',
    'Pages' => 'පිටු',
    'Branches' => 'ශාඛා',
    'Students and parents' => 'සිසුන් සහ දෙමාපියන්',
    'Log in to see classes, marks, homework and fees.' => 'පන්ති, ලකුණු, ගෙදර වැඩ සහ ගාස්තු බැලීමට පිවිසෙන්න.',
    'Science with {name}' => '{name} ගුරුතුමිය සමඟ විද්‍යාව',
    'Science for Grades {r} at {n} branches, in class every week and online between lessons.' => 'ශාඛා {n}ක {r} ශ්‍රේණි සඳහා විද්‍යාව: සතිපතා පන්තියේදී, සහ පාඩම් අතර කාලයේ මාර්ගගතව.',
    '{name} teaching a Science lesson' => '{name} ගුරුතුමිය විද්‍යා පාඩමක් උගන්වමින්',
    'Your teacher' => 'ඔබේ ගුරුතුමිය',
    '{name} teaches Science for Grades {r} at {n} branches, following the school syllabus step by step.' => '{name} ගුරුතුමිය ශාඛා {n}ක {r} ශ්‍රේණිවලට විද්‍යාව උගන්වන්නේ පාසල් විෂය නිර්දේශය පියවරෙන් පියවර අනුගමනය කරමිනි.',
    'Lessons with smart-board presentations' => 'ස්මාර්ට් බෝඩ් ඉදිරිපත් කිරීම් සහිත පාඩම්',
    'Recordings and notes for every month, to revise at home' => 'නිවසේදී පුනරීක්ෂණය සඳහා සෑම මාසයකම පටිගත කිරීම් සහ සටහන්',
    'Quizzes, homework and past papers, marked with feedback' => 'ප්‍රතිචාර සමඟ ලකුණු දෙන ප්‍රශ්නාවලි, ගෙදර වැඩ සහ පසුගිය ප්‍රශ්න පත්‍ර',
    'Parents can follow marks, attendance and fees in the portal' => 'දෙමාපියන්ට ද්වාරයෙන් ලකුණු, පැමිණීම සහ ගාස්තු බලාගත හැක',
    'In class' => 'පන්තියේදී',
    'Learning together, every week' => 'සතිපතා, එකට ඉගෙන ගනිමු',
    'Each grade has its own weekly class at the branch. Students who miss a lesson can catch up from the recording and notes, and the class register lets parents know about an absence.' => 'සෑම ශ්‍රේණියකටම ශාඛාවේ සතිපතා පන්තියක් ඇත. පාඩමක් මග හැරුණු සිසුන්ට පටිගත කිරීම සහ සටහන් මගින් එය ආවරණය කරගත හැකි අතර, පන්ති ලේඛනය මගින් නොපැමිණීම ගැන දෙමාපියන්ට දැනුම් දෙයි.',
    'See the timetable' => 'කාලසටහන බලන්න',
    '{name} with her students in class' => '{name} ගුරුතුමිය පන්තියේදී සිසුන් සමඟ',
    'Would you like your child to join?' => 'ඔබේ දරුවා පන්තියට එක් කිරීමට කැමතිද?',
    'Send an inquiry and the branch office will call you back.' => 'විමසීමක් එවන්න, ශාඛා කාර්යාලය ඔබට නැවත අමතයි.',
    'Join a class' => 'පන්තියට එක්වන්න',
    'Talk to the branch office' => 'ශාඛා කාර්යාලය අමතන්න',
    'Call the branch nearest to you, or send a message and the office will reply.' => 'ඔබට ආසන්නම ශාඛාවට අමතන්න, නැතහොත් පණිවිඩයක් එවන්න, කාර්යාලය පිළිතුරු දෙයි.',
    'Branch contact details will appear here soon.' => 'ශාඛා සම්බන්ධතා විස්තර ඉක්මනින් මෙහි පෙන්වනු ඇත.',
    'Phone number coming soon' => 'දුරකථන අංකය ඉක්මනින්',
    'Send a message' => 'පණිවිඩයක් එවන්න',
    'For joining a class, the enrolment inquiry is quickest:' => 'පන්තියට එක්වීමට, ලියාපදිංචි විමසීම වේගවත්ම ක්‍රමයයි:',
    'Send message' => 'පණිවිඩය යවන්න',
    'teacher (honorific)' => 'ගුරුතුමිය',
    'with Science' => 'සමඟ විද්‍යාව',
    'Learn Science with' => 'විද්‍යාව ඉගෙන ගන්න',
    'Weekly Science classes for Grades {r}, following the school syllabus. Every lesson is backed by recordings, notes, quizzes and homework in the portal, and parents can follow their child\'s progress.' => 'පාසල් විෂය නිර්දේශය අනුව {r} ශ්‍රේණි සඳහා සතිපතා විද්‍යා පන්ති. සෑම පාඩමකටම ද්වාරයේ පටිගත කිරීම්, සටහන්, ප්‍රශ්නාවලි සහ ගෙදර වැඩ ඇති අතර, දෙමාපියන්ට දරුවාගේ ප්‍රගතිය බලාගත හැක.',
    'Science teacher' => 'විද්‍යා ගුරුතුමිය',
    'branches' => 'ශාඛා',
    'grades' => 'ශ්‍රේණි',
    'weekly classes' => 'සතිපතා පන්ති',
    'medium' => 'මාධ්‍යය',
    'How it works' => 'ක්‍රියා කරන ආකාරය',
    'Term test and model papers for each grade, with marking schemes released after the class has tried them.' => 'සෑම ශ්‍රේණියකටම වාර විභාග සහ ආදර්ශ ප්‍රශ්න පත්‍ර, පන්තිය ඒවා කළ පසු ලකුණු දීමේ පටිපාටි සමඟ.',
    'Absence alerts' => 'නොපැමිණීමේ දැනුම්දීම්',
    'If a child is marked absent, the family gets an alert in the parent portal.' => 'දරුවා නොපැමිණි ලෙස සලකුණු කළොත්, පවුලට දෙමාපිය ද්වාරයේ දැනුම්දීමක් ලැබේ.',
    'Sign in to the class portal' => 'පන්ති ද්වාරයට පිවිසෙන්න',
    'Your classes, notes, recordings, quizzes and marks, in one place.' => 'ඔබේ පන්ති, සටහන්, පටිගත කිරීම්, ප්‍රශ්නාවලි සහ ලකුණු, එකම තැනක.',
    'Joining' => 'එක්වීම',
    'Four steps to join' => 'පියවර හතරකින් එක්වන්න',
    'Send an inquiry' => 'විමසීමක් එවන්න',
    'Fill in the form below or call the branch nearest to you.' => 'පහත පෝරමය පුරවන්න, නැතහොත් ඔබට ආසන්නම ශාඛාවට අමතන්න.',
    'Register at the office' => 'කාර්යාලයේ ලියාපදිංචි වන්න',
    'The office registers your child and gives the student ID and a first password.' => 'කාර්යාලය ඔබේ දරුවා ලියාපදිංචි කර සිසු අංකය සහ පළමු මුරපදය ලබා දෙයි.',
    'Come to class every week' => 'සෑම සතියකම පන්තියට එන්න',
    'Weekly class at the branch, with notes, recordings and quizzes online.' => 'ශාඛාවේ සතිපතා පන්තිය, සටහන්, පටිගත කිරීම් සහ ප්‍රශ්නාවලි මාර්ගගතව.',
    'Follow the progress' => 'ප්‍රගතිය බලාගන්න',
    'Parents log in with their phone number to see marks, attendance and fees.' => 'ලකුණු, පැමිණීම සහ ගාස්තු බැලීමට දෙමාපියන් දුරකථන අංකයෙන් පිවිසේ.',
    'Call' => 'අමතන්න',
    'Weekly classes by grade' => 'ශ්‍රේණිය අනුව සතිපතා පන්ති',
    'Recordings, notes and quizzes online' => 'මාර්ගගතව පටිගත කිරීම්, සටහන් සහ ප්‍රශ්නාවලි',
    'A parent login to follow progress' => 'ප්‍රගතිය බැලීමට දෙමාපිය පිවිසුමක්',
    '{name} explaining a lesson on the board' => '{name} ගුරුතුමිය පුවරුවේ පාඩමක් පැහැදිලි කරමින්',
    'Lesson time' => 'පාඩම් කාලය',
    'Students doing an experiment' => 'පරීක්ෂණයක් කරන සිසුන්',
    'Experiments' => 'පරීක්ෂණ',
    'Students in the science lab' => 'විද්‍යාගාරයේ සිසුන්',
    'Science lab' => 'විද්‍යාගාරය',
    'Students sitting a paper' => 'ප්‍රශ්න පත්‍රයක් ලියන සිසුන්',
    'Paper practice' => 'ප්‍රශ්න පත්‍ර පුහුණුව',
    'Photos from the classes' => 'පන්තිවල ඡායාරූප',
    'Choose a photo' => 'ඡායාරූපයක් තෝරන්න',
    'Photo {n}' => 'ඡායාරූපය {n}',

    // Motivation: levels, achievements, streaks, goals (migration 015)
    '7-Day Streak' => 'දින 7 අඛණ්ඩ ඉගෙනීම',
    'A Science unit' => 'විද්‍යා ඒකකයක්',
    'A small dip, not a fall. One good quiz this week brings you right back.' => 'මෙය කුඩා අඩුවීමක් පමණයි. මේ සතියේ හොඳ ප්‍රශ්නාවලියක් ඔබව නැවත ඉහළට ගෙන එයි.',
    'Achieved' => 'සාර්ථකයි',
    'Achiever' => 'ජයග්‍රාහකයා',
    'All my classes' => 'මගේ සියලු පන්ති',
    'Attend 90% of your classes in the last 30 days (at least 4 classes).' => 'පසුගිය දින 30 තුළ ඔබේ පන්තිවලින් 90%කට සහභාගී වන්න (අවම පන්ති 4ක්).',
    'Attend every class in the last 30 days (at least 4 classes).' => 'පසුගිය දින 30 තුළ සෑම පන්තියකටම සහභාගී වන්න (අවම පන්ති 4ක්).',
    'Attend {n}% of classes' => 'පන්තිවලින් {n}%කට සහභාගී වීම',
    'Attended 90% of classes in 30 days.' => 'දින 30ක් තුළ පන්තිවලින් 90%කට සහභාගී විය.',
    'Attended every class in 30 days.' => 'දින 30ක් තුළ සෑම පන්තියකටම සහභාගී විය.',
    'Beat your last quiz mark by 15 points.' => 'ඔබේ පෙර ප්‍රශ්නාවලි ලකුණ ලකුණු 15කින් ඉක්මවන්න.',
    'Beat your own best quiz mark.' => 'ඔබේම හොඳම ප්‍රශ්නාවලි ලකුණ ඉක්මවන්න.',
    'Beat {n}% in your next quiz.' => 'ඊළඟ ප්‍රශ්නාවලියේදී {n}% ඉක්මවන්න.',
    'By' => 'දිනය දක්වා',
    'Choose a type of goal.' => 'ඉලක්ක වර්ගයක් තෝරන්න.',
    'Choose an end date between today and six months from now.' => 'අද සිට මාස හයක් ඇතුළත අවසන් දිනයක් තෝරන්න.',
    'Choose the Science unit for this goal.' => 'මෙම ඉලක්කය සඳහා විද්‍යා ඒකකය තෝරන්න.',
    'Current streak: {n} days.' => 'දැනට අඛණ්ඩව දින {n}.',
    'Do a quiz, homework or open a lesson today to start one.' => 'ආරම්භ කිරීමට අද ප්‍රශ්නාවලියක්, ගෙදර වැඩක් කරන්න හෝ පාඩමක් විවෘත කරන්න.',
    'Do quizzes and homework that are tagged with a unit.' => 'ඒකකයකට සම්බන්ධ ප්‍රශ්නාවලි සහ ගෙදර වැඩ කරන්න.',
    'Early Finisher' => 'කලින් නිම කරන්නා',
    'Earned' => 'ලබා ගත්තා',
    'Earned {d}' => 'ලබා ගත් දිනය {d}',
    'Every Science champion starts with one quiz. Your first one sets your level.' => 'සෑම විද්‍යා ශූරයෙක්ම පටන් ගන්නේ එක් ප්‍රශ්නාවලියකින්. ඔබේ පළමු ප්‍රශ්නාවලිය ඔබේ මට්ටම තීරණය කරයි.',
    'Explorer' => 'ගවේෂකයා',
    'Full Attendance' => 'පූර්ණ පැමිණීම',
    'Goal' => 'ඉලක්කය',
    'Goal removed.' => 'ඉලක්කය ඉවත් කළා.',
    'Goal saved. Your progress towards it updates by itself.' => 'ඉලක්කය සුරැකුණා. ඒ කරා ඔබේ ප්‍රගතිය ස්වයංක්‍රීයව යාවත්කාලීන වේ.',
    'Goal set. The student will see it on their home page.' => 'ඉලක්කය සකසා ඇත. සිසුවාට එය තම මුල් පිටුවේ පෙනේ.',
    'Hand in 20 quizzes.' => 'ප්‍රශ්නාවලි 20ක් භාර දෙන්න.',
    'Hand in 5 homework tasks on time.' => 'ගෙදර වැඩ 5ක් නියමිත වේලාවට භාර දෙන්න.',
    'Hand in 5 quizzes.' => 'ප්‍රශ්නාවලි 5ක් භාර දෙන්න.',
    'Hand in a quiz to unlock this.' => 'මෙය විවෘත කිරීමට ප්‍රශ්නාවලියක් භාර දෙන්න.',
    'Hand in homework a day or more early, 3 times.' => 'ගෙදර වැඩ දිනකට හෝ ඊට වැඩි කලින් තුන් වතාවක් භාර දෙන්න.',
    'Hand in two quizzes, then beat your first mark.' => 'ප්‍රශ්නාවලි දෙකක් භාර දී, ඔබේ පළමු ලකුණ ඉක්මවන්න.',
    'Hand in {n} more quizzes to unlock this.' => 'මෙය විවෘත කිරීමට තවත් ප්‍රශ්නාවලි {n}ක් භාර දෙන්න.',
    'Hand in {n}% of homework' => 'ගෙදර වැඩවලින් {n}%ක් භාර දීම',
    'Handed in 20 quizzes.' => 'ප්‍රශ්නාවලි 20ක් භාර දුන්නා.',
    'Handed in 5 homework tasks on time.' => 'ගෙදර වැඩ 5ක් නියමිත වේලාවට භාර දුන්නා.',
    'Handed in 5 quizzes.' => 'ප්‍රශ්නාවලි 5ක් භාර දුන්නා.',
    'Handed in homework a day early, 3 times.' => 'ගෙදර වැඩ දිනකට කලින් තුන් වතාවක් භාර දුන්නා.',
    'Homework Hero' => 'ගෙදර වැඩ වීරයා',
    'Homework handed in' => 'භාර දුන් ගෙදර වැඩ',
    'Improvement Champion' => 'දියුණුවේ ශූරයා',
    'Keep every part strong to stay at {level}' => '{level} මට්ටමේ රැඳී සිටීමට සෑම කොටසක්ම ශක්තිමත්ව තබා ගන්න',
    'Learn on 7 days in a row (one rest day allowed).' => 'දින 7ක් අඛණ්ඩව ඉගෙන ගන්න (එක් විවේක දිනයකට ඉඩ ඇත).',
    'Learned on 7 days in a row.' => 'දින 7ක් අඛණ්ඩව ඉගෙන ගත්තා.',
    'Learner' => 'ඉගෙනුම්කරුවා',
    'Learning streak' => 'අඛණ්ඩ ඉගෙනීම',
    'Level' => 'මට්ටම',
    'Levels are for encouragement in this class only. They are not school grades.' => 'මට්ටම් මෙම පන්තියේ දිරිගැන්වීම සඳහා පමණි. ඒවා පාසල් ශ්‍රේණි නොවේ.',
    'My goals' => 'මගේ ඉලක්ක',
    'My level' => 'මගේ මට්ටම',
    'Needs at least 4 marked classes in the last 30 days ({n} so far).' => 'පසුගිය දින 30 තුළ ලකුණු කළ පන්ති අවම 4ක් අවශ්‍යයි (දැනට {n}).',
    'Needs at least 6 marked quizzes ({n} so far).' => 'ලකුණු කළ ප්‍රශ්නාවලි අවම 6ක් අවශ්‍යයි (දැනට {n}).',
    'No goals yet. Set one below. Your progress updates by itself from your marks, attendance and homework.' => 'තවම ඉලක්ක නැත. පහතින් එකක් සකසන්න. ඔබේ ලකුණු, පැමිණීම සහ ගෙදර වැඩ අනුව ප්‍රගතිය ස්වයංක්‍රීයව යාවත්කාලීන වේ.',
    'Not reached' => 'ළඟා නොවුණා',
    'Nothing to measure yet' => 'තවම මැනීමට දෙයක් නැත',
    'Now {n}%' => 'දැන් {n}%',
    'One rest day never breaks your learning streak.' => 'එක් විවේක දිනයකින් ඔබේ අඛණ්ඩ ඉගෙනීම බිඳෙන්නේ නැහැ.',
    'Only goals you set yourself can be removed.' => 'ඉවත් කළ හැක්කේ ඔබම සැකසූ ඉලක්ක පමණි.',
    'Only {n} points to {level}. You are very close.' => '{level} මට්ටමට තව ලකුණු {n}ක් පමණයි. ඔබ ඉතා ළඟයි.',
    'Personal Best' => 'පුද්ගලික හොඳම',
    'Progress score {n} out of 100' => 'ප්‍රගති ලකුණ 100න් {n}',
    'Quiz Explorer' => 'ප්‍රශ්නාවලි ගවේෂකයා',
    'Quiz Master' => 'ප්‍රශ්නාවලි ප්‍රවීණයා',
    'Quiz average of {n}%' => 'ප්‍රශ්නාවලි සාමාන්‍යය {n}%',
    'Raise your average by 15 points (last 3 quizzes compared with your first 3).' => 'ඔබේ සාමාන්‍යය ලකුණු 15කින් ඉහළ නංවන්න (අවසන් ප්‍රශ්නාවලි 3 පළමු 3 සමඟ සසඳා).',
    'Raised your average by 15 points.' => 'සාමාන්‍යය ලකුණු 15කින් ඉහළ නැංවූවා.',
    'Reached on {d}' => '{d} දින ළඟා වුණා',
    'Regular Attender' => 'නිතිපතා පැමිණෙන්නා',
    'Remove goal' => 'ඉලක්කය ඉවත් කරන්න',
    'Save goal' => 'ඉලක්කය සුරකින්න',
    'Science Champion' => 'විද්‍යා ශූරයා',
    'Science Star' => 'විද්‍යා තරුව',
    'Score 80% or more in a Science unit (at least 20 marks assessed).' => 'විද්‍යා ඒකකයකින් 80% හෝ ඊට වැඩි ලබා ගන්න (අවම ලකුණු 20ක් ඇගයූ).',
    'Scored 80% or more in a Science unit.' => 'විද්‍යා ඒකකයකින් 80% හෝ ඊට වැඩි ලබා ගත්තා.',
    'See all achievements' => 'සියලු ජයග්‍රහණ බලන්න',
    'Set a goal' => 'ඉලක්කයක් සකසන්න',
    'Set by {name}' => 'සැකසුවේ {name}',
    'Small steps every day add up. Pick one goal below and start today.' => 'දිනපතා කුඩා පියවර එකතු වී විශාල වෙනසක් වේ. පහතින් ඉලක්කයක් තෝරා අදම පටන් ගන්න.',
    'Starter' => 'ආරම්භකයා',
    'Target %' => 'ඉලක්කය %',
    'That class is not one of yours.' => 'එම පන්තිය ඔබේ පන්තියක් නොවේ.',
    'That unit is not part of your grade.' => 'එම ඒකකය ඔබේ ශ්‍රේණියට අයත් නොවේ.',
    'The target must be between 1 and 100%.' => 'ඉලක්කය 1% සහ 100% අතර විය යුතුයි.',
    'Top level reached' => 'ඉහළම මට්ටමට ළඟා වුණා',
    'Topic Master' => 'ඒකක ප්‍රවීණයා',
    'Unit' => 'ඒකකය',
    'You can have up to {n} goals of your own at a time.' => 'ඔබට එක වර ඔබේම ඉලක්ක {n}ක් දක්වා තබා ගත හැක.',
    'You can remove only goals you set.' => 'ඔබට ඉවත් කළ හැක්කේ ඔබ සැකසූ ඉලක්ක පමණි.',
    'You have reached the top level. Keep it steady and help a friend who is stuck.' => 'ඔබ ඉහළම මට්ටමට ළඟා වී ඇත. එය එලෙසම පවත්වා ගෙන අපහසුවෙන් සිටින මිතුරෙකුට උදව් කරන්න.',
    'Your best so far is {n}%.' => 'මෙතෙක් ඔබේ හොඳම ලකුණ {n}%.',
    'Your marks are up {n} points on last month. That is real progress.' => 'ඔබේ ලකුණු පසුගිය මාසයට වඩා ලකුණු {n}කින් ඉහළයි. එය සැබෑ දියුණුවක්.',
    'Your recent average is {n} points above your first quizzes.' => 'ඔබේ මෑත සාමාන්‍යය පළමු ප්‍රශ්නාවලිවලට වඩා ලකුණු {n}කින් ඉහළයි.',
    'Your strongest unit is at {n}%.' => 'ඔබේ ශක්තිමත්ම ඒකකය {n}%.',
    'days' => 'දින',
    'until {d}' => '{d} දක්වා',
    'your teacher' => 'ඔබේ ගුරුතුමිය',
    '{a} of {b}' => '{b}න් {a}',
    '{a} of {b} opened.' => '{b}න් {a}ක් විවෘත කළා.',
    '{n} classes in a row so far.' => 'දැනට අඛණ්ඩව පන්ති {n}.',
    '{n} in a row at 70% or more right now.' => 'දැනට අඛණ්ඩව 70% හෝ ඊට වැඩි {n}ක්.',
    '{n} learning days in a row. Keep the streak alive today.' => 'අඛණ්ඩව ඉගෙනුම් දින {n}යි. අදත් එය පවත්වා ගන්න.',
    '{n} more early hand-ins to go.' => 'තවත් කලින් භාරදීම් {n}ක් ඉතිරියි.',
    '{n} more on-time hand-ins to go.' => 'තවත් නියමිත වේලාවට භාරදීම් {n}ක් ඉතිරියි.',
    '{n} more to reach {m} days' => 'දින {m} වෙත ළඟා වීමට තව {n}යි',
    '{n} of {m} of your own' => 'ඔබේම {m}න් {n}',
    '{n} points to Level {l} · {name}' => 'මට්ටම {l} · {name} වෙත ලකුණු {n}',
