    'Published — the class can see it' => 'පළ කර ඇත — පන්තියට එය දැකිය හැක',
    'e.g. Chemical Reactions - full lesson recording' => 'උදා: රසායනික ප්‍රතික්‍රියා - සම්පූර්ණ පාඩම් පටිගත කිරීම',

