    'Branch (leave as "every branch" when targeting a grade across all of them)' => 'ශාඛාව (ශ්‍රේණියක් සියලු ශාඛා හරහා ඉලක්ක කරන විට "සියලු ශාඛා" ලෙස තබන්න)',
    'Cancel my registration' => 'මගේ ලියාපදිංචිය අවලංගු කරන්න',
