    'Cancelled' => 'අවලංගු කළා',
    'Cover image link (optional)' => 'කවර රූපයේ සබැඳිය (අත්‍යවශ්‍ය නොවේ)',
    'Delete' => 'මකන්න',
    'Delete this draft?' => 'මෙම කෙටුම්පත මකන්නද?',
    'Draft deleted.' => 'කෙටුම්පත මකා දැමුවා.',
