    'Online link' => 'අන්තර්ජාල සබැඳිය',
    'Online link (optional)' => 'අන්තර්ජාල සබැඳිය (අත්‍යවශ්‍ය නොවේ)',
    'Only a draft can be deleted; publish it then cancel it instead.' => 'කෙටුම්පතක් පමණක් මැකිය හැක; ඒ වෙනුවට එය ප්‍රකාශයට පත් කර පසුව අවලංගු කරන්න.',
    'Published. {n} people notified.' => 'ප්‍රකාශයට පත් කළා. පුද්ගලයින් {n} දෙනෙකුට දැනුම් දුන්නා.',
    'Registration cancelled.' => 'ලියාපදිංචිය අවලංගු කළා.',
    'Registration is not open for that seminar.' => 'එම සම්මන්ත්‍රණය සඳහා ලියාපදිංචිය විවෘත නැත.',
    'Requires registration (people can RSVP from their own seminars list)' => 'ලියාපදිංචිය අවශ්‍යයි (පුද්ගලයින්ට ඔවුන්ගේම සම්මන්ත්‍රණ ලැයිස්තුවෙන් RSVP කළ හැක)',
    'Seminar cancelled.' => 'සම්මන්ත්‍රණය අවලංගු කළා.',
