    'Seminars, workshops and events for a class, a grade, a branch, or every branch.' => 'පන්තියක්, ශ්‍රේණියක්, ශාඛාවක් හෝ සියලු ශාඛා සඳහා සම්මන්ත්‍රණ, වැඩමුළු සහ උත්සව.',
    'That seminar is not available.' => 'එම සම්මන්ත්‍රණය ලබා ගත නොහැක.',
    'That seminar is not yours to change.' => 'එම සම්මන්ත්‍රණය වෙනස් කිරීමට ඔබට අවසර නැත.',
    'Time (optional)' => 'වේලාව (අත්‍යවශ්‍ය නොවේ)',
    'Venue' => 'ස්ථානය',
    'Venue (optional)' => 'ස්ථානය (අත්‍යවශ්‍ය නොවේ)',
    'Who this is for' => 'මෙය කා සඳහාද',
    'Write a title, pick a date, choose who should see it, and check any links.' => 'මාතෘකාවක් ලියන්න, දිනයක් තෝරන්න, එය කාටද පෙනිය යුතුද යි තෝරන්න, සබැඳි ඇත්නම් පරීක්ෂා කරන්න.',
