    'Capacity (optional -- leave blank for unlimited)' => 'ධාරිතාව (විකල්ප -- සීමා රහිත සඳහා හිස්ව තබන්න)',
    'e.g. 60' => 'උදා: 60',
    'Once full, new registrations join a waiting list and are added automatically if a spot opens up.' => 'පිරී ගිය පසු, නව ලියාපදිංචි කිරීම් රැඳී සිටින ලැයිස්තුවට එක් වේ, ආසනයක් ලැබුණු විට ස්වයංක්‍රීයව ලියාපදිංචි වේ.',
    'Who this is for and who should see it can no longer be changed -- it has already been published and announced.' => 'මෙය කා සඳහාද සහ කවුරුන් එය දැකිය යුතුද යන්න තවදුරටත් වෙනස් කළ නොහැක -- එය දැනටමත් ප්‍රකාශයට පත් කර දැනුම් දී ඇත.',
    'This seminar is full -- you have been added to the waiting list and will be registered automatically if a spot opens up.' => 'මෙම සම්මන්ත්‍රණය පිරී ඇත -- ඔබ රැඳී සිටින ලැයිස්තුවට එක් කර ඇත, ආසනයක් ලැබුණු විට ඔබ ස්වයංක්‍රීයව ලියාපදිංචි වනු ඇත.',
    'Write a title, pick a date, and check any links.' => 'මාතෘකාවක් ලියන්න, දිනයක් තෝරන්න, සහ ලින්ක් පරීක්ෂා කරන්න.',
    'Choose who should see it, within your own branch, grade or classes.' => 'ඔබේම ශාඛාව, ශ්‍රේණිය හෝ පන්ති තුළ, කවුරුන් එය දැකිය යුතුද තෝරන්න.',
    'Seminar updated.' => 'සම්මන්ත්‍රණය යාවත්කාලීන කරන ලදී.',

    // Users page, payments page, parent account, calendar heading
    'Admins, coordinators, staff and teachers. Students are managed separately.' => 'පරිපාලකයින්, සම්බන්ධීකාරකයින්, කාර්ය මණ්ඩලය සහ ගුරුවරුන්. සිසුන් වෙනම කළමනාකරණය කෙරේ.',
