    'Averaging under 50% over two or more quizzes -- not one bad paper.' => 'ප්‍රශ්නාවලි දෙකක් හෝ වැඩි ගණනක සාමාන්‍යය 50%ට අඩු -- එක් නරක ප්‍රශ්න පත්‍රයක් පමණක් නොවේ.',
