    'Will appear on the home page once published.' => 'ප්‍රකාශයට පත් කළ පසු මුල් පිටුවේ පෙන්වනු ඇත.',
    'The poster could not be uploaded. Please try again.' => 'පෝස්ටරය උඩුගත කළ නොහැකි විය. කරුණාකර නැවත උත්සාහ කරන්න.',
    'The poster must be a JPG, PNG or WEBP image.' => 'පෝස්ටරය JPG, PNG හෝ WEBP රූපයක් විය යුතුය.',
    'The poster must be 3MB or smaller.' => 'පෝස්ටරය 3MB හෝ ඊට අඩු විය යුතුය.',

    // Users page, confirm box
    'User Management' => 'පරිශීලක කළමනාකරණය',
    'Enabled' => 'සක්‍රියයි',
    'Disabled' => 'අක්‍රියයි',
    'Reset Password' => 'මුරපදය යළි සකසන්න',
    'ID Card' => 'හැඳුනුම්පත',
    'Make inactive' => 'අක්‍රිය කරන්න',
    'Activate' => 'සක්‍රිය කරන්න',
    'Yes, continue' => 'ඔව්, ඉදිරියට',
    'This is your own account. Change your details from My Profile.' => 'මෙය ඔබේම ගිණුමයි. ඔබේ විස්තර මගේ පැතිකඩෙන් වෙනස් කරන්න.',
    'Only the super admin can change an admin account.' => 'පරිපාලක ගිණුමක් වෙනස් කළ හැක්කේ ප්‍රධාන පරිපාලකට පමණි.',
    'Works in more than one branch, so only the super admin can change this account.' => 'ශාඛා එකකට වඩා වැඩ කරන නිසා, මෙම ගිණුම වෙනස් කළ හැක්කේ ප්‍රධාන පරිපාලකට පමණි.',
    'Switch off {name}\'s account? They will be signed out and cannot log in until it is switched on again.' => '{name}ගේ ගිණුම අක්‍රිය කරන්නද? ඔවුන් පද්ධතියෙන් ඉවත් වන අතර නැවත සක්‍රිය කරන තුරු පිවිසිය නොහැක.',
    'Delete {name} permanently? This cannot be undone. To keep their history, make the account inactive instead.' => '{name} ස්ථිරවම මකන්නද? මෙය ආපසු හැරවිය නොහැක. ඉතිහාසය තබා ගැනීමට, ගිණුම අක්‍රිය කරන්න.',
    'Delete the class {name}? This cannot be undone.' => '{name} පන්තිය මකන්නද? මෙය ආපසු හැරවිය නොහැක.',
    'Delete the branch {name}? This cannot be undone.' => '{name} ශාඛාව මකන්නද? මෙය ආපසු හැරවිය නොහැක.',
    'Generate monthly invoices for all active enrollments for this period?' => 'මෙම කාලය සඳහා සියලු සක්‍රිය ලියාපදිංචි කිරීම්වලට මාසික ඉන්වොයිස් සාදන්නද?',
    'Mark this payment as paid?' => 'මෙම ගෙවීම ගෙවූ ලෙස සලකුණු කරන්නද?',
    'Confirm payment collection for this month?' => 'මෙම මාසයේ ගෙවීම ලැබුණු බව තහවුරු කරන්නද?',
    'Remove question {n}?' => '{n} වන ප්‍රශ්නය ඉවත් කරන්නද?',
    'Deactivate this guardian\'s login? The student and any other guardian are not affected.' => 'මෙම භාරකරුගේ පිවිසුම අක්‍රිය කරන්නද? සිසුවාට සහ වෙනත් භාරකරුවන්ට බලපෑමක් නැත.',
    'Approve this workflow?' => 'මෙම ඉල්ලීම අනුමත කරන්නද?',
