    'A unique Registration Number (e.g.' => 'අනන්‍ය ලියාපදිංචි අංකයක් (උදා.',
    'will be automatically generated and shown after saving. The user uses it to login and will set their own password on first login.' => 'සුරැකීමෙන් පසු ස්වයංක්‍රීයව ජනනය වී පෙන්වනු ලැබේ. පරිශීලකයා එය පිවිසීමට භාවිතා කරන අතර පළමු පිවිසීමේදී තමාගේම මුරපදය සකසනු ඇත.',
    '1. Profile Photo' => '1. පැතිකඩ ඡායාරූපය',
    'Upload Photo' => 'ඡායාරූපය උඩුගත කරන්න',
