    'Teacher (TCH)' => 'ගුරුවරයා (TCH)',
    'Select role to see assigned ID prefix.' => 'පවරා ඇති හැඳුනුම්පත් උපසර්ගය බැලීමට තත්ත්වය තෝරන්න.',
    'Province' => 'පළාත',
    'Optional internal notes...' => 'විකල්ප අභ්‍යන්තර සටහන්...',
