    'No role-specific features are offered for this role.' => 'මෙම භූමිකාව සඳහා විශේෂිත විශේෂාංග නොමැත.',
    'Feature' => 'විශේෂාංගය',
    'Visible' => 'දිස්වේ',
    'Hidden' => 'සැඟවී ඇත',
    'Changes take effect immediately upon saving, and only affect what this role sees in the sidebar.' => 'වෙනස්කම් සුරැකීමෙන් වහාම ක්‍රියාත්මක වන අතර, මෙම භූමිකාව පැති තීරුවේ දකින දෑ පමණක් බලපායි.',
    'Save Feature Visibility' => 'විශේෂාංග දෘශ්‍යතාව සුරකින්න',
    'Show or hide a feature\'s nav link per role. The underlying page stays as protected as it already was — this only changes what shows up in the sidebar.' => 'එක් එක් භූමිකාව අනුව විශේෂාංගයක නාවික සබැඳිය පෙන්වන්න හෝ සඟවන්න. මූලික පිටුව කලින් සිටි පරිදිම ආරක්ෂිතව පැවතේ — මෙය පැති තීරුවේ පෙනෙන දෑ පමණක් වෙනස් කරයි.',
    'Parent / Guardian' => 'මාපිය / භාරකරු',
