    'Create pending payment fee records for all active student enrollments for the specified billing cycle.' => 'නියමිත බිල්පත් කාලසීමාව සඳහා සියලුම ක්‍රියාත්මක ශිෂ්‍ය ලියාපදිංචි කිරීම් සඳහා පොරොත්තු ගෙවීම් ගාස්තු වාර්තා සාදන්න.',
